  const cleanEnv = { ...process.env };
  const RALPH_ENV_VARS = ['KSPEC_RALPH_SESSION', 'KSPEC_SESSION_ID'];
  for (const key of RALPH_ENV_VARS) {
    if (!(key in env)) {
